const { useState } = React;

function App() {
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [role, setRole] = useState("");
  const [errors, setErrors] = useState({});

  const validateEmail = (email) => {
    // Simple email regex
    return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email);
  };

  const handleLogin = (e) => {
    e.preventDefault();
    const newErrors = {};

    if (!email.trim()) {
      newErrors.email = "Email is required.";
    } else if (!validateEmail(email)) {
      newErrors.email = "Please enter a valid email.";
    }

    if (!password.trim()) {
      newErrors.password = "Password is required.";
    }

    if (!role) {
      newErrors.role = "Role is required.";
    }

    setErrors(newErrors);

    if (Object.keys(newErrors).length === 0) {
      alert(`Logged in as ${email} with role ${role}`);
    }
  };

  return (
    <>
      <style>{`
        * {
          box-sizing: border-box;
        }
        body,html,#root {
          margin: 0; padding: 0; height: 100%; font-family: Arial, sans-serif;
          background: #f9f9f9;
        }
        .container {
          display: flex;
          height: 100vh;
          max-width: 900px;
          margin: auto;
          background: white;
          box-shadow: 0 0 15px rgba(0,0,0,0.1);
          border-radius: 8px;
          overflow: hidden;
        }
        .left {
          flex: 1;
          background-color: #e0e7ff;
          display: flex;
          justify-content: center;
          align-items: center;
          padding: 20px;
        }
        .left img {
          max-width: 100%;
          max-height: 100%;
          object-fit: contain;
          border-radius: 6px;
        }
        .right {
          flex: 1;
          padding: 40px 30px;
          display: flex;
          flex-direction: column;
          justify-content: center;
        }
        h1 {
          margin: 0 0 10px 0;
          font-weight: 600;
          font-size: 28px;
          color: #222;
        }
        p.subtitle {
          margin: 0 0 25px 0;
          color: #555;
          font-size: 14px;
        }
        form {
          display: flex;
          flex-direction: column;
        }
        label {
          font-size: 14px;
          margin-bottom: 6px;
          color: #333;
          font-weight: 500;
        }
        input, select {
          padding: 10px 12px;
          font-size: 14px;
          border: 1.8px solid #ccc;
          border-radius: 4px;
          margin-bottom: 18px;
          transition: border-color 0.3s;
        }
        input:focus, select:focus {
          border-color: #4f46e5;
          outline: none;
        }
        button {
          background-color: #4f46e5;
          color: white;
          font-weight: 600;
          padding: 12px 0;
          border: none;
          border-radius: 4px;
          cursor: pointer;
          font-size: 16px;
          margin-top: 5px;
          transition: background-color 0.3s;
        }
        button:hover {
          background-color: #4338ca;
        }
        .error {
          color: #dc2626;
          font-size: 13px;
          margin-top: -14px;
          margin-bottom: 14px;
          font-weight: 500;
        }
        .help-link {
          margin-top: 18px;
          font-size: 13px;
          color: #4f46e5;
          text-decoration: underline;
          cursor: pointer;
          width: fit-content;
        }
        .help-link:hover {
          color: #4338ca;
        }
      `}</style>
      <div className="container" role="main">
        <section className="left" aria-label="Illustration">
          <img src="/runtime/photos/product.jpg" alt="Illustration" />
        </section>
        <section className="right" aria-label="Admin login form">
          <h1>Admin Portal</h1>
          <p className="subtitle">Please sign in to continue</p>
          <form onSubmit={handleLogin} noValidate>
            <label htmlFor="email">Email</label>
            <input
              id="email"
              type="email"
              value={email}
              onChange={(e) => setEmail(e.target.value)}
              aria-describedby={errors.email ? "email-error" : undefined}
              aria-invalid={errors.email ? "true" : "false"}
              placeholder="Email"
            />
            {errors.email && <p id="email-error" role="alert" className="error">{errors.email}</p>}

            <label htmlFor="password">Password</label>
            <input
              id="password"
              type="password"
              value={password}
              onChange={(e) => setPassword(e.target.value)}
              aria-describedby={errors.password ? "password-error" : undefined}
              aria-invalid={errors.password ? "true" : "false"}
              placeholder="Password"
            />
            {errors.password && <p id="password-error" role="alert" className="error">{errors.password}</p>}

            <label htmlFor="role">Role</label>
            <select
              id="role"
              value={role}
              onChange={(e) => setRole(e.target.value)}
              aria-describedby={errors.role ? "role-error" : undefined}
              aria-invalid={errors.role ? "true" : "false"}
            >
              <option value="">Role</option>
              <option value="Admin">Admin</option>
              <option value="Editor">Editor</option>
              <option value="Viewer">Viewer</option>
            </select>
            {errors.role && <p id="role-error" role="alert" className="error">{errors.role}</p>}

            <button type="submit">Login</button>
          </form>
          <a href="#" className="help-link">Need help?</a>
        </section>
      </div>
    </>
  );
}

ReactDOM.createRoot(document.getElementById("root")).render(<App />);

